#!/bin/bash
# MNIST auto-encoder 784-1000-500-250-30: --lam sweep over ['1e-5', '1e-3', '1e-1'], all 7 arms per value. Writes to benchmarks/outputs/sweeps/mnist_autoencoder_lam/<value>/.
# Generated by benchmarks/slurm/generate_jobs.py — edit that file, not this one.
# See docs/reports/plan_exp_step1.md §6 and benchmarks/slurm/README.md.
# Submit from the repository root:  sbatch benchmarks/slurm/sweep_mnist_autoencoder_lam.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=mnist_autoencoder_lam_sweep
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=00:20:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: 3 values x 7 arms x T_reference; see SWEEPS in generate_jobs.py for the per-value measurement.
# Dataset: mnist must be staged under $SLURM_SUBMIT_DIR/dataset (compute nodes have no
# internet; --no-allow-download turns a missing dataset into a clear error, not a timeout).

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src:$SLURM_SUBMIT_DIR"

# Hyperparameter sweep: the full 7-arm WCT protocol, once per --lam value, each into its
# own output directory. Every value re-derives its own budget from its own reference arm, so the
# arms of one value are comparable to each other; values are comparable to each other only in the
# sense that they share the model, the seed and the nominal epoch count.
#
# Why this sweep exists: see SWEEPS in benchmarks/slurm/generate_jobs.py.
for VALUE in 1e-5 1e-3 1e-1; do
  echo "=== --lam $VALUE ==="
  python -m benchmarks.mnist_autoencoder.bench \
    --arms diag kfac ekfac tkfac tekfac adam adamw \
    --epochs 20 \
    --budget-mode wct \
    --reference-arm diag \
    --max-epoch-factor 3 \
    --lr-schedule budget \
    --lam "$VALUE" \
    --num-workers 8 \
    --no-allow-download \
    --data-root "$SLURM_SUBMIT_DIR/dataset" \
    --checkpoints 0,0.01,0.1,0.5,1 \
    --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/sweeps/mnist_autoencoder_lam/$VALUE"
done
